'use client';

import React, { createContext, useContext, ReactNode, useState, useCallback, useRef } from 'react';
import { SageCore } from '@/core/sage-core';

interface SageContextType {
  core: SageCore;
  cameraStream: MediaStream | null;
  requestCamera: (mode?: 'user' | 'environment') => Promise<MediaStream | null>;
  stopCamera: () => void;
  facingMode: 'user' | 'environment';
  flipCamera: () => Promise<void>;
}

const SageContext = createContext<SageContextType | null>(null);

export function SageProvider({ children, core }: { children: ReactNode; core: SageCore }) {
  const [cameraStream, setCameraStream] = useState<MediaStream | null>(null);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');
  const streamRef = useRef<MediaStream | null>(null);

  const stopCamera = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
      setCameraStream(null);
    }
  }, []);

  const requestCamera = useCallback(async (mode: 'user' | 'environment' = facingMode) => {
    try {
      // If we already have a stream with the right mode, return it
      if (streamRef.current && streamRef.current.active) {
        const videoTrack = streamRef.current.getVideoTracks()[0];
        const settings = videoTrack.getSettings();
        if (settings.facingMode === mode) {
          return streamRef.current;
        }
        // Otherwise stop it to switch modes
        stopCamera();
      }

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: 640, height: 480, frameRate: { ideal: 15, max: 30 }, facingMode: mode },
      });

      streamRef.current = stream;
      setCameraStream(stream);
      setFacingMode(mode);
      return stream;
    } catch (err) {
      console.error('SAGE_CAMERA_ERROR:', err);
      return null;
    }
  }, [facingMode, stopCamera]);

  const flipCamera = useCallback(async () => {
    const newMode = facingMode === 'user' ? 'environment' : 'user';
    await requestCamera(newMode);
  }, [facingMode, requestCamera]);

  return (
    <SageContext.Provider value={{ core, cameraStream, requestCamera, stopCamera, facingMode, flipCamera }}>
      {children}
    </SageContext.Provider>
  );
}

export function useSage() {
  const context = useContext(SageContext);
  if (!context) {
    throw new Error('useSage must be used within a SageProvider');
  }
  return context;
}
